command_events.command:
/bin/zsh -lc "snap='/var/folders/qt/4kz3_8fn6hx612tyl9tj4dbm0000gn/T/itbench-aa-public-76df38a82288/Scenario-34'
print -r -- 'OTEL-DEMO POD SNAPSHOT STATUS'
while IFS="'$'"'\\t' read -r ts tst trace span flags sev sevnum svc body rest; do
  clean="'${body//'"\\\"\\\"/\\\"}
  case \""'$clean" in
    *'"'\"kind\":\"Pod\"'*'\"namespace\":\"otel-demo\"'*)
      name="'${clean#*'"'\"metadata\":'*'\"name\":\"'}; name="'${name%%'"'\"'*}
      phase="'${clean##*'"'\"phase\":\"'}; phase="'${phase%%'"'\"'*}
      node="'${clean##*'"'\"nodeName\":\"'}; node="'${node%%'"'\"'*}
      print -r -- \""'$name | phase=$phase | node=$node"
      case "$clean" in *'"'\"reason\":\"'*|*'CrashLoopBackOff'*|*'OOMKilled'*|*'terminated'*|*'waiting'*) print -r -- \"  "'${clean[-1800,-1]}";; esac
    ;;
  esac
done < "$snap/k8s_objects_raw.tsv"
print -r -- '"'NODE SNAPSHOT CONDITIONS'
while IFS="'$'"'\\t' read -r ts tst trace span flags sev sevnum svc body rest; do
  clean="'${body//'"\\\"\\\"/\\\"}
  case \""'$clean" in *'"'\"kind\":\"Node\"'*) name="'${clean#*'"'\"metadata\":'*'\"name\":\"'}; name="'${name%%'"'\"'*}; print -r -- \""'$name | ${clean[-2500,-1]}";; esac
done < "$snap/k8s_objects_raw.tsv"'
